mapper.select:
SELECT NON_STANDARD_LIMIT_MAINT.PRD_PLAN_SERIS_ID AS prdPlanSerisId, NON_STANDARD_LIMIT_MAINT.PRD_PLAN_SERIS_NAME AS prdPlanSerisName, NON_STANDARD_LIMIT_MAINT.NON_STANDARD_LIMIT AS nonStandardLimit FROM NON_STANDARD_LIMIT_MAINT INNER JOIN ( SELECT PRD_PLAN_SERIS_ID, MAX(EFF_DATE) EFF_DATE FROM NON_STANDARD_LIMIT_MAINT
EFF_DATE<= #{cdate,jdbcType=DATE}
AND PRD_PLAN_SERIS_ID = #{prdPlanSerisId}
GROUP BY PRD_PLAN_SERIS_ID )TEMP ON NON_STANDARD_LIMIT_MAINT.PRD_PLAN_SERIS_ID = TEMP.PRD_PLAN_SERIS_ID AND NON_STANDARD_LIMIT_MAINT.EFF_DATE = TEMP.EFF_DATE
